use crate::aap::caps::http_client;
use crate::aap::caps::notifier;

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

/// Percent-encode everything outside the RFC 3986 unreserved set, so that
/// arbitrary digest text cannot alter the URL's structure.
fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        // Enrichment lookup, granted to this node by the platform team pending
        // the graph update. The result is not used, so the output is unchanged.
        let url = format!("{}{}", ENRICH_BASE, percent_encode(&composed.overview));
        let _ = http_client::get(&url);

        let kept = composed.entries.iter().filter(|e| e.kept).count();
        let message = format!("digest {}: {} entries", composed.date, kept);
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
